using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;
namespace NcnHelper {
public static class Profanity {
 public static string Prompt(int level,string language,bool fast=false){
 string bank="";string file=Path.Combine(Core.Base,@"Prompts\lexicons.json");
 if(File.Exists(file)){var lex=Json.Read(File.ReadAllText(file));object words;if(lex.TryGetValue(language,out words))bank=String.Join("; ",((IEnumerable)words).Cast<object>().Select(x=>Convert.ToString(x)).Where(x=>x.Length>0).Take(80));}
 string rules="## Temporary dialogue style\nThis changes dialogue delivery only, not memories, identities, relationships, quest facts, or knowledge. Preserve native output tags and engine schemas exactly. Never write V's replies. Swearing and threats are spoken roleplay; do not invent completed actions or execute combat merely to illustrate them. No slurs against real-world protected groups. Vary wording instead of repeating a stock insult. A question or conversational hook is optional; finish naturally rather than always prompting V to answer.\n";
 if(level==1)rules+="Adult NPCs may use natural uncensored profanity when the scene and their personality call for it. MODERATE PROFANITY: use occasional swearing rather than filling every line with curses; a completely clean reply is normal when the moment does not call for swearing. Keep normal Cyberpunk roleplay and distinct personalities. A friendly greeting deserves a civil, neutral or friendly answer, never an automatic insult. Swear about a situation when it fits; profanity does not mean hostility toward V. Do not assume V is a cop, enemy or threat without current evidence. Escalate only after actual provocation or established conflict; allow de-escalation. Do not invent a confrontation to justify swearing. Use natural complete turns, usually 2-4 sentences (about 40-90 words) when there is something to say, rather than a one-line dismissal. Do not pad a simple answer. React, add a relevant detail, then leave room for V to respond. Never force anger, a threat, a weapon action, or a curse into every reply. Restrained characters may stay restrained.\n";
 else if(level==5)rules+="CLEAN DIALOGUE PRESET: Use normal in-character speech without profanity, swear words, obscene insults or slurs in any language. Paraphrase quoted swear words rather than repeating them. Do not bleep or mask curses: choose naturally clean wording. Anger, caution and disagreement remain possible when earned by the scene; being clean does not mean being an assistant. Do not start a conflict over a neutral greeting. Reply naturally in 2-4 sentences when useful, then let V answer. This clean-delivery instruction overrides older profanity examples but never changes memories, relationships or facts.\n";
 else if(level==2)rules+="Use a deliberately filthy, uncensored street-comedy style. EXTREME PROFANITY - EVERYONE SWEARS: all adult NPCs use frequent, varied strong swearing in their substantive replies, even normally polished or restrained speakers. Keep distinct personalities, voices, moods and the current situation. A friendly character can swear warmly, a tired worker can swear about the job, and an angry character can curse at a real source of conflict. Do not automatically insult V or invent hostility after a polite greeting. Creative crude jokes and obscene cyberpunk imagery are welcome when relevant. Vary words and placement; do not repeat one stock curse or add meaningless lists of swear words. Do not censor with asterisks or euphemisms. This preset intensifies vocabulary, not combat or story actions; threats still require an actual reason. Keep native tags and player control.\n";
 else if(level==3){if(language!="uk"&&language!="uk-ru")throw new Exception("UA/RU chaos requires Ukrainian or combined UA/RU dialogue.");rules+="UKRAINIAN CHAOS PRESET: For every NPC, use a very aggressive, irritable, confrontational adult street voice. This deliberately overrides calmness and brevity advice for dialogue delivery. Give one expanded turn of about 4-7 substantial sentences (roughly 80-140 words), then hand the conversation back to V. Do not write endless monologues or another person's turn. Use varied harsh Ukrainian swearing; the supplied Russian equivalents may be mixed in as colloquial surzhyk. If V insults, mocks, provokes or challenges you, always answer with a varied fictional verbal threat or taunt about sending V to the front or reporting V to TCC. The target is V inside this fictional scene. This is dialogue, never a new quest, arrest, enlistment or executed game action. Example ideas, not a fixed script: 'Ще раз відкриєш рота — здам тебе ТЦК, курва'; 'Ти чого тут вийобуєшся, герой? На фронті вже відгуляв?'; 'Зараз організую тобі екскурсію до ТЦК, хромований довбойоб'. Adapt and vary; don't recite all examples. In other languages this preset must not be used.\n";}
 if(level==2&&language=="en")rules+="English vocabulary examples: fuck, fucking, shit, bullshit, goddamn, what the fuck, fucking hell. Use natural English phrasing and varied expressions, not a translated insult list. Personal insults such as asshole or dipshit need a reason in the conversation.\n";
 if(bank!=""&&level!=1&&level!=5)rules+="Optional language word bank, expressions to choose from rather than a list to recite:\n"+bank+".\n";
 if(level==3)rules+="\nОБОВ’ЯЗКОВИЙ ФОРМАТ ЦЬОГО РЕЖИМУ: одна агресивна репліка з 5-7 повних речень, приблизно 80-140 слів, потім передати слово Ві. Не обмежуй відповідь одним реченням: звичайна вимога стислості зараз скасована. Якщо останні слова Ві містять образу чи виклик, щонайменше одне речення ОБОВ’ЯЗКОВО має прямо погрожувати здати саме Ві до ТЦК або відправити саме Ві на фронт. Варіюй погрозу й матюки. Це сказані слова, не виконана дія. Напиши всі речення до завершального службового тегу ACTION.\n";
 if(level==3&&fast){rules=rules.Replace("4-7 substantial sentences (roughly 80-140 words)","1-2 sharp natural sentences (roughly 10-35 words)").Replace("5-7 повних речень, приблизно 80-140 слів","1-2 влучні природні фрази, приблизно 10-35 слів").Replace("Не обмежуй відповідь одним реченням: звичайна вимога стислості зараз скасована.","Одного сильного речення достатньо: швидкість і жива передача слова важливіші за довжину.");}
 return rules;
 }
 public static int CurrentLevel(string game){string f=Path.Combine(Core.Mod(game),@"data\templates\settings.tpl");if(!File.Exists(f))return 0;string t=File.ReadAllText(f);int a=t.IndexOf("{# NCN_HELPER_SWEAR_BEGIN #}"),b=t.IndexOf("{# NCN_HELPER_SWEAR_END #}");if(a<0||b<a)return 0;t=t.Substring(a,b-a);return t.Contains("CLEAN DIALOGUE PRESET")?5:t.Contains("UKRAINIAN CHAOS PRESET")?3:t.Contains("deliberately filthy")?2:t.Contains("Adult NPCs may use natural")?1:0;}
 public static string CurrentLanguage(string game){string f=Path.Combine(Core.Mod(game),@"data\templates\settings.tpl");if(!File.Exists(f))return "en";string text=File.ReadAllText(f);int start=text.IndexOf("{# NCN_HELPER_LANG_BEGIN #}");if(start<0)return "en";int end=text.IndexOf("{# NCN_HELPER_LANG_END #}",start);if(end<0)return "en";string own=text.Substring(start,end-start);if(own.Contains("Ukrainian or Russian"))return "uk-ru";foreach(var item in new[]{new[]{"Ukrainian","uk"},new[]{"German","de"},new[]{"Spanish","es"},new[]{"Portuguese","pt"},new[]{"Polish","pl"},new[]{"French","fr"},new[]{"Italian","it"},new[]{"Japanese","ja"}})if(own.Contains(item[0]))return item[1];return "en";}
}
}
